SELECT fn_cp_import_case('routier-controle-de-nuit-vehicule-suspect', '{"slug": "routier-controle-de-nuit-vehicule-suspect", "title": "Trois occupants, coffre chargé de câbles de cuivre", "theme_slug": "circulation", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 3 heures du matin. Vous contrôlez, dans une zone industrielle déserte, un véhicule occupé par trois personnes dont le coffre, ouvert à votre demande, révèle une quantité importante de câbles de cuivre visiblement récupérés, sans qu''aucune explication immédiate et convaincante ne soit apportée sur leur provenance. L''heure et le lieu, une zone industrielle à cette heure tardive, renforcent le caractère évocateur de cette découverte sans pour autant constituer une certitude.\n\nVous êtes seule avec votre collègue face à ces trois occupants, ce qui constitue un effectif numériquement inférieur dans l''hypothèse où la situation devrait évoluer vers une confrontation plus directe. Les trois hommes restent pour l''instant coopératifs, bien que visiblement mal à l''aise face à vos questions sur le contenu du coffre.\n\nCette situation, née d''un contrôle routier ordinaire, débouche potentiellement sur une problématique de vols de métaux qui dépasse le cadre initial de cette interception, sans que les éléments à ce stade ne permettent de trancher entre plusieurs explications possibles.", "questions": [{"position": 1, "max_points": 5, "label": "Comment sécurisez-vous ce contrôle compte tenu de votre effectif réduit face à trois occupants dans un lieu isolé ?", "hint": "L''effectif numériquement défavorable dans un lieu isolé impose une gestion prudente de la disposition et de la communication avant toute escalade de la situation.", "perfect": "Je reste consciente de cet effectif numériquement défavorable, deux contre trois, dans ce lieu isolé à cette heure tardive, ce qui m''incite à une prudence particulière dans la gestion de ce contrôle.\n\nJe maintiens une disposition qui me permet de garder une vision sur l''ensemble des trois occupants, en évitant de me retrouver dans une position où je ne pourrais surveiller qu''une partie du groupe à la fois.\n\nJe sollicite un renfort compte tenu de cette configuration numérique défavorable et du caractère isolé du lieu, cette précaution étant justifiée avant même que la situation ne s''aggrave éventuellement.\n\nJe reste attentive à toute évolution du comportement des trois hommes, un changement d''attitude collectif pouvant nécessiter une réaction rapide de ma part face à ce déséquilibre numérique.", "points": [{"position": 1, "label": "Rester consciente de l''effectif numériquement défavorable et du lieu isolé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : prudence particulière face à ce déséquilibre.", "groups": [{"position": 1, "keywords": ["effectif défavorable", "lieu isolé", "prudence particulière"]}]}, {"position": 2, "label": "Maintenir une disposition permettant une vision sur les trois occupants", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter de surveiller qu''une partie du groupe à la fois.", "groups": [{"position": 1, "keywords": ["disposition maîtrisée", "vision sur tous", "surveillance complète"]}]}, {"position": 3, "label": "Solliciter un renfort compte tenu de cette configuration numérique", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Précaution avant l''aggravation éventuelle.", "groups": [{"position": 1, "keywords": ["renfort sollicité", "configuration numérique", "avant l''aggravation"]}]}, {"position": 4, "label": "Rester attentive à toute évolution collective du comportement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réaction rapide face au déséquilibre numérique.", "groups": [{"position": 1, "keywords": ["évolution collective", "réaction rapide", "déséquilibre numérique"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment traitez-vous la découverte de ces câbles de cuivre sans explication convaincante sur leur provenance ?", "hint": "L''absence d''explication convaincante, combinée au contexte, justifie d''approfondir sans pour autant conclure prématurément à une culpabilité.", "perfect": "Je recueille les explications de chacun des trois occupants séparément si possible, cette séparation permettant de vérifier la cohérence de leurs versions respectives sur la provenance de ces câbles.\n\nJe reste attentive au caractère évocateur du contexte, l''heure tardive et la zone industrielle déserte, sans pour autant considérer ces éléments comme une preuve suffisante en l''absence de tout autre élément objectif.\n\nJe recherche si un signalement de vol de câbles de cuivre a pu être fait récemment dans le secteur, cette vérification pouvant rapidement orienter la suite de mes investigations.\n\nJe consigne avec précision l''ensemble des éléments constatés, notamment la nature exacte et la quantité des câbles découverts, ces éléments matériels étant essentiels pour la suite du traitement de cette affaire.", "points": [{"position": 1, "label": "Recueillir les explications de chacun séparément pour vérifier la cohérence", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vérifier la cohérence des versions respectives.", "groups": [{"position": 1, "keywords": ["explications séparées", "cohérence des versions", "provenance des câbles"]}]}, {"position": 2, "label": "Rester attentive au contexte évocateur sans le considérer comme une preuve", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Heure et lieu évocateurs mais non suffisants seuls.", "groups": [{"position": 1, "keywords": ["contexte évocateur", "pas une preuve suffisante", "autres éléments nécessaires"]}]}, {"position": 3, "label": "Rechercher un signalement récent de vol de câbles dans le secteur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vérification pouvant orienter rapidement l''enquête.", "groups": [{"position": 1, "keywords": ["signalement de vol", "secteur vérifié", "orienter l''enquête"]}]}, {"position": 4, "label": "Consigner précisément la nature et la quantité des câbles découverts", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éléments matériels essentiels pour la suite.", "groups": [{"position": 1, "keywords": ["consigner précisément", "nature et quantité", "éléments matériels"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment poursuivez-vous cette affaire au-delà du seul cadre du contrôle routier initial ?", "hint": "Une découverte fortuite débouchant sur une problématique plus large nécessite une articulation correcte entre le cadre initial et la suite des investigations.", "perfect": "Je transmets l''ensemble des éléments recueillis aux services compétents en matière d''investigation sur les vols de métaux, cette problématique dépassant le cadre initial de ce simple contrôle routier.\n\nJe m''assure que le cadre juridique de cette découverte, née d''un contrôle routier ordinaire, soit correctement articulé avec la suite des investigations qui pourraient être engagées sur l''origine de ces câbles.\n\nJe reste factuelle dans mon rapport, en distinguant clairement ce qui relève de la constatation objective de ce qui relève de mes hypothèses sur la provenance possible de ces biens.\n\nJe garde à l''esprit que cette affaire pourrait s''inscrire dans un phénomène plus large de vols de métaux dans le secteur, cette information pouvant être utile aux services d''enquête pour établir d''éventuels liens avec d''autres faits similaires.", "points": [{"position": 1, "label": "Transmettre aux services compétents en investigation sur les vols de métaux", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : problématique dépassant le cadre du contrôle routier.", "groups": [{"position": 1, "keywords": ["services compétents", "vols de métaux", "dépasse le contrôle routier"]}]}, {"position": 2, "label": "S''assurer que le cadre juridique de la découverte soit correctement articulé", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Suite des investigations bien articulée.", "groups": [{"position": 1, "keywords": ["cadre juridique articulé", "suite des investigations", "découverte fortuite"]}]}, {"position": 3, "label": "Rester factuelle en distinguant constatation et hypothèses", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rapport clair sur ce qui est constaté et ce qui est supposé.", "groups": [{"position": 1, "keywords": ["factuelle", "constatation vs hypothèses", "rapport clair"]}]}, {"position": 4, "label": "Considérer un possible lien avec un phénomène plus large de vols de métaux", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information utile aux services d''enquête.", "groups": [{"position": 1, "keywords": ["phénomène plus large", "liens possibles", "utile à l''enquête"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-enfant-sans-dispositif-retenue', '{"slug": "routier-enfant-sans-dispositif-retenue", "title": "Le bébé est sur les genoux de sa mère à l''avant", "theme_slug": "circulation", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 8 h 15. Lors d''un contrôle routier de routine, vous constatez qu''un nourrisson de quelques mois est installé sur les genoux de sa mère, assise à l''avant du véhicule, sans aucun dispositif de retenue adapté. La mère, visiblement pressée, vous explique qu''elle a dû improviser ce trajet en urgence pour une raison familiale et que le siège auto habituel de l''enfant est resté chez sa grand-mère.\n\nCette absence totale de protection pour un nourrisson constitue un danger vital immédiat en cas de choc, même à faible vitesse, sans qu''aucune circonstance d''urgence invoquée ne puisse justifier cette exposition au risque pour l''enfant. La mère semble sincèrement inconsciente de la gravité de ce danger, considérant son geste comme une simple entorse ponctuelle et sans grande conséquence.\n\nCette situation, banale dans son apparence de contrôle routier ordinaire, révèle un danger vital immédiat pour ce nourrisson qui nécessite une réponse claire, indépendamment des explications avancées par la mère pour justifier cette absence de dispositif adapté.", "questions": [{"position": 1, "max_points": 5, "label": "Comment qualifiez-vous le danger que représente ce nourrisson sans dispositif de retenue, malgré les explications de sa mère ?", "hint": "L''urgence invoquée par la mère ne réduit en rien le danger vital objectif que court l''enfant dans ces conditions.", "perfect": "Je qualifie cette situation comme un danger vital immédiat pour ce nourrisson, l''absence totale de dispositif de retenue exposant l''enfant à des conséquences potentiellement mortelles en cas de choc, même à faible vitesse.\n\nJe ne minimise pas ce danger au motif de l''urgence invoquée par la mère, cette explication n''atténuant en rien le risque objectif couru par l''enfant durant tout le trajet effectué dans ces conditions.\n\nJe reste attentive au fait que la mère semble sincèrement inconsciente de la gravité de ce danger, cette inconscience nécessitant une information claire de ma part plutôt qu''une simple sanction sans pédagogie.\n\nJe considère que cette situation impose une action immédiate et non un simple avertissement, le danger vital pour l''enfant primant sur toute autre considération dans l''instant.", "points": [{"position": 1, "label": "Qualifier comme danger vital immédiat pour le nourrisson", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : conséquences potentiellement mortelles en cas de choc.", "groups": [{"position": 1, "keywords": ["danger vital immédiat", "conséquences mortelles", "même à faible vitesse"]}]}, {"position": 2, "label": "Ne pas minimiser le danger malgré l''urgence invoquée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "L''urgence n''atténue pas le risque objectif.", "groups": [{"position": 1, "keywords": ["pas minimisé par l''urgence", "risque objectif", "pendant tout le trajet"]}]}, {"position": 3, "label": "Reconnaître son inconscience sincère nécessitant une information claire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Plutôt qu''une simple sanction sans pédagogie.", "groups": [{"position": 1, "keywords": ["inconscience sincère", "information claire", "pédagogie nécessaire"]}]}, {"position": 4, "label": "Considérer une action immédiate plutôt qu''un simple avertissement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Danger vital primant sur toute autre considération.", "groups": [{"position": 1, "keywords": ["action immédiate", "pas un simple avertissement", "danger vital prime"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment agissez-vous concrètement pour ne pas laisser repartir ce véhicule dans les mêmes conditions ?", "hint": "L''urgence de la situation familiale invoquée par la mère ne doit pas primer sur la sécurité immédiate de l''enfant pour la suite du trajet.", "perfect": "Je ne laisse pas ce véhicule repartir dans les mêmes conditions, cette poursuite du trajet sans dispositif de retenue prolongeant un danger que je ne peux pas ignorer une fois constaté.\n\nJe recherche avec la mère une solution concrète pour la suite de son trajet, comme la possibilité d''emprunter un dispositif de retenue temporaire ou d''organiser un transport alternatif pour elle et son enfant.\n\nJe reste attentive à ne pas transformer cette intervention en une situation de blocage total qui ne résoudrait rien, en cherchant activement une issue pratique plutôt qu''un simple constat d''impossibilité de continuer.\n\nJe m''assure que la mère comprenne bien que cette exigence n''est pas une simple formalité administrative, mais une nécessité vitale pour la sécurité immédiate de son enfant durant tout trajet ultérieur.", "points": [{"position": 1, "label": "Ne pas laisser repartir le véhicule dans les mêmes conditions", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : ne pas prolonger le danger constaté.", "groups": [{"position": 1, "keywords": ["pas de départ dans les mêmes conditions", "danger prolongé", "ne pas ignorer"]}]}, {"position": 2, "label": "Rechercher une solution concrète pour la suite du trajet", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Dispositif temporaire ou transport alternatif.", "groups": [{"position": 1, "keywords": ["solution concrète", "dispositif temporaire", "transport alternatif"]}]}, {"position": 3, "label": "Chercher activement une issue pratique plutôt qu''un blocage total", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter une situation qui ne résoudrait rien.", "groups": [{"position": 1, "keywords": ["issue pratique", "pas de blocage total", "solution active"]}]}, {"position": 4, "label": "S''assurer qu''elle comprenne que c''est une nécessité vitale, pas une formalité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sécurité immédiate pour tout trajet ultérieur.", "groups": [{"position": 1, "keywords": ["nécessité vitale", "pas une formalité", "trajets ultérieurs"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment concluez-vous cette intervention en tenant compte à la fois de la gravité du fait et de la sincérité apparente de cette mère ?", "hint": "La conclusion doit combiner fermeté sur l''infraction et pédagogie constructive, sans céder à l''un ou l''autre de manière disproportionnée.", "perfect": "Je constate l''infraction avec la rigueur qu''elle mérite, ce danger vital pour le nourrisson ne pouvant être traité comme un simple oubli sans conséquence sur le plan de la qualification retenue.\n\nJe profite de cette occasion pour expliquer clairement à cette mère les risques concrets qu''elle a fait courir à son enfant, cette dimension pédagogique pouvant avoir un effet plus durable qu''une simple sanction sèche.\n\nJe reste bienveillante dans le ton employé, reconnaissant sa sincérité apparente et son absence d''intention de nuire, sans que cette bienveillance ne dilue pour autant la fermeté nécessaire sur le fond.\n\nJe m''assure qu''elle reparte avec une compréhension claire de l''importance de ce dispositif pour tout trajet futur, cette prise de conscience étant l''objectif principal au-delà du seul traitement de cet incident ponctuel.", "points": [{"position": 1, "label": "Constater l''infraction avec la rigueur qu''elle mérite", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : danger vital non traité comme un simple oubli.", "groups": [{"position": 1, "keywords": ["rigueur maintenue", "pas un simple oubli", "qualification retenue"]}]}, {"position": 2, "label": "Expliquer clairement les risques concrets pour un effet pédagogique durable", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Plus efficace qu''une simple sanction sèche.", "groups": [{"position": 1, "keywords": ["explication pédagogique", "risques concrets", "effet durable"]}]}, {"position": 3, "label": "Rester bienveillante dans le ton sans diluer la fermeté", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaître la sincérité sans minimiser le fond.", "groups": [{"position": 1, "keywords": ["bienveillance dans le ton", "sincérité reconnue", "fermeté maintenue"]}]}, {"position": 4, "label": "S''assurer d''une compréhension claire pour les trajets futurs", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prise de conscience comme objectif principal.", "groups": [{"position": 1, "keywords": ["compréhension claire", "trajets futurs", "prise de conscience"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-conducteur-age-desoriente-au-volant', '{"slug": "routier-conducteur-age-desoriente-au-volant", "title": "Il tourne depuis un quart d''heure et ne sait plus où il va", "theme_slug": "circulation", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 16 heures. Un riverain vous signale un véhicule qui tourne en boucle autour d''un rond-point depuis un quart d''heure, sans jamais en sortir. Le conducteur, un homme d''une soixantaine d''années, semble désorienté lorsque vous l''interceptez, incapable de vous dire précisément où il se rendait ni de retrouver son chemin, alors qu''il conduit visiblement dans ce quartier depuis longtemps selon ses propres explications hésitantes.\n\nCet homme reste digne et poli dans ses échanges avec vous, sans agressivité ni signe évident d''ébriété ou de trouble aigu, mais sa confusion sur sa destination et son incapacité à formuler un trajet cohérent posent question sur son aptitude actuelle à conduire en toute sécurité. Il insiste néanmoins pour reprendre la route dès que possible, visiblement gêné par cette situation.\n\nCette situation croise la question de la sécurité routière avec celle de la vulnérabilité potentielle d''une personne âgée, sans qu''aucun élément ne permette de trancher avec certitude si cette désorientation relève d''un épisode ponctuel ou d''une difficulté plus installée nécessitant une réponse au-delà de ce seul contrôle.", "questions": [{"position": 1, "max_points": 5, "label": "Comment évaluez-vous l''aptitude de cet homme à reprendre le volant compte tenu de sa désorientation constatée ?", "hint": "La dignité de cette personne ne doit pas empêcher une évaluation rigoureuse de sa capacité réelle à conduire en sécurité dans l''instant.", "perfect": "J''évalue avec attention sa capacité actuelle à conduire en sécurité, cette désorientation prolongée sur un simple rond-point constituant un indice sérieux qui ne peut être ignoré malgré son calme apparent et sa dignité dans l''échange.\n\nJe lui pose des questions simples sur sa situation et son trajet prévu, cette évaluation informelle me permettant d''apprécier l''ampleur de sa confusion sans pour autant poser un diagnostic qui ne relève pas de ma compétence.\n\nJe reste attentive au fait que l''absence d''agressivité ou de signe d''ébriété ne suffit pas à écarter un problème d''aptitude à la conduite, cette désorientation pouvant relever de causes très diverses qui nécessitent toutes une même prudence immédiate.\n\nJe ne le laisse pas reprendre le volant tant que cette évaluation ne me permet pas d''être raisonnablement rassurée sur sa capacité à circuler en sécurité, cette précaution primant sur son insistance à vouloir repartir rapidement.", "points": [{"position": 1, "label": "Évaluer sa capacité actuelle à conduire malgré son calme apparent", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : désorientation comme indice sérieux malgré la dignité.", "groups": [{"position": 1, "keywords": ["capacité évaluée", "indice sérieux", "malgré le calme"]}]}, {"position": 2, "label": "Poser des questions simples sans poser de diagnostic médical", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Évaluation informelle ne relevant pas de ma compétence.", "groups": [{"position": 1, "keywords": ["questions simples", "évaluation informelle", "pas de diagnostic"]}]}, {"position": 3, "label": "Considérer que l''absence d''agressivité ne suffit pas à écarter un problème", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Causes diverses nécessitant la même prudence.", "groups": [{"position": 1, "keywords": ["absence d''agressivité insuffisante", "causes diverses", "même prudence"]}]}, {"position": 4, "label": "Ne pas le laisser reprendre le volant tant que non rassurée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Précaution primant sur son insistance à repartir.", "groups": [{"position": 1, "keywords": ["ne pas laisser repartir", "précaution prioritaire", "insistance non suivie"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment empêchez-vous la reprise du volant tout en préservant la dignité de cet homme ?", "hint": "L''empêchement nécessaire d''une reprise de conduite doit se faire avec ménagement pour ne pas humilier une personne par ailleurs digne et coopérative.", "perfect": "Je lui explique avec tact et respect les raisons de mon inquiétude, sans le traiter comme un incapable mais en partageant honnêtement mon observation de sa confusion sur ce trajet précis.\n\nJe recherche avec lui une solution qui préserve sa dignité, comme la possibilité de contacter un proche qui pourrait venir le chercher ou l''accompagner, plutôt qu''une interdiction sèche et unilatérale de reprendre son véhicule.\n\nJe reste ferme sur la nécessité de ne pas le laisser repartir seul dans l''immédiat, tout en évitant tout ton condescendant qui pourrait blesser cet homme visiblement déjà gêné par sa propre situation.\n\nJe m''assure de son confort et de sa sécurité pendant l''attente d''une solution, cette situation pouvant elle-même être source d''anxiété supplémentaire qu''il convient d''apaiser autant que possible.", "points": [{"position": 1, "label": "Expliquer avec tact les raisons de l''inquiétude sans le traiter d''incapable", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : partager l''observation avec respect.", "groups": [{"position": 1, "keywords": ["tact et respect", "pas incapable", "observation partagée"]}]}, {"position": 2, "label": "Rechercher une solution préservant sa dignité, comme contacter un proche", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Plutôt qu''une interdiction sèche et unilatérale.", "groups": [{"position": 1, "keywords": ["solution digne", "contacter un proche", "pas d''interdiction sèche"]}]}, {"position": 3, "label": "Rester ferme sans ton condescendant", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter de blesser une personne déjà gênée.", "groups": [{"position": 1, "keywords": ["ferme sans condescendance", "pas blessant", "déjà gêné"]}]}, {"position": 4, "label": "S''assurer de son confort pendant l''attente d''une solution", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Apaiser l''anxiété supplémentaire de la situation.", "groups": [{"position": 1, "keywords": ["confort assuré", "anxiété apaisée", "pendant l''attente"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite de cette situation au-delà de ce seul incident ponctuel ?", "hint": "Cette désorientation isolée pourrait être le signe avant-coureur d''une difficulté plus installée qui mérite un signalement adapté.", "perfect": "Je transmets cette situation aux services compétents en matière de suivi de l''aptitude à la conduite, cette désorientation pouvant révéler une difficulté plus installée qui dépasse le seul incident de ce jour.\n\nJe recommande, si des proches peuvent être contactés, qu''une attention particulière soit portée à sa capacité de conduite à l''avenir, sans pour autant poser moi-même un pronostic qui ne relève pas de ma compétence.\n\nJe consigne avec précision les circonstances de cette désorientation, notamment sa durée et les éléments observés, ces informations pouvant être utiles pour une évaluation médicale ultérieure si elle devait être engagée.\n\nJe reste attentive à ne pas dramatiser excessivement cette situation auprès de lui, un épisode isolé pouvant aussi avoir des causes bénignes et passagères qu''il convient de ne pas exagérer par précipitation.", "points": [{"position": 1, "label": "Transmettre aux services compétents en suivi de l''aptitude à la conduite", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : difficulté possiblement plus installée.", "groups": [{"position": 1, "keywords": ["services compétents", "aptitude à la conduite", "difficulté installée"]}]}, {"position": 2, "label": "Recommander une attention des proches sans poser de pronostic", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pas de compétence pour un diagnostic.", "groups": [{"position": 1, "keywords": ["attention des proches", "pas de pronostic", "hors compétence"]}]}, {"position": 3, "label": "Consigner précisément les circonstances de la désorientation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Utile pour une évaluation médicale ultérieure.", "groups": [{"position": 1, "keywords": ["consigner précisément", "durée et éléments", "évaluation médicale"]}]}, {"position": 4, "label": "Ne pas dramatiser excessivement auprès de lui", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Épisode isolé pouvant avoir des causes bénignes.", "groups": [{"position": 1, "keywords": ["pas de dramatisation", "causes bénignes possibles", "pas de précipitation"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-rodeo-motorise-quartier', '{"slug": "routier-rodeo-motorise-quartier", "title": "Une dizaine de deux-roues, des habitants filment aux balcons", "theme_slug": "circulation", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 20 heures. Une dizaine de deux-roues motorisés effectuent des figures dangereuses dans un quartier résidentiel, roulant à vive allure et sur une roue devant des habitants excédés, dont plusieurs filment la scène depuis leurs balcons, visiblement dans l''intention de dénoncer publiquement ce phénomène qui semble se répéter régulièrement. Votre arrivée sur zone est immédiatement perçue par le groupe, qui réagit en intensifiant ses figures plutôt qu''en cherchant à se disperser.\n\nUne éventuelle poursuite de ces deux-roues dans les rues étroites de ce quartier résidentiel, à cette heure où de nombreux habitants circulent encore à pied, ferait courir un risque considérable tant aux pilotes eux-mêmes qu''aux tiers présents, ce risque devant être mis en balance avec la pression légitime des riverains qui attendent une réponse ferme à ce phénomène récurrent.\n\nCette situation collective et publique, avec une forte exposition médiatique potentielle du fait des vidéos prises depuis les balcons, complique la décision tactique immédiate face à ce défi ouvertement lancé par le groupe de pilotes à votre arrivée.", "questions": [{"position": 1, "max_points": 5, "label": "Comment évaluez-vous l''opportunité d''engager une poursuite de ce groupe de deux-roues dans ce quartier résidentiel ?", "hint": "Le risque créé par une poursuite dans ces conditions doit être mis en balance avec la gravité du phénomène et son caractère récurrent.", "perfect": "Je considère qu''une poursuite dans ces rues étroites, à une heure où de nombreux piétons circulent encore, créerait un risque disproportionné par rapport à l''objectif recherché, ce risque touchant potentiellement les pilotes eux-mêmes autant que les habitants présents.\n\nJe reste consciente que ce risque doit être mis en balance avec la gravité du phénomène et son caractère manifestement récurrent selon les habitants, sans que cette pression légitime ne doive pour autant me conduire à une décision qui aggraverait le danger global de la situation.\n\nJe privilégie une approche qui renonce à la poursuite immédiate au profit d''une identification différée, cette option permettant de traiter le phénomène sans créer le danger supplémentaire d''une course-poursuite dans ce contexte résidentiel.\n\nJe reste attentive à ne pas laisser le défi apparent lancé par ce groupe à mon arrivée influencer ma décision tactique, cette provocation ne devant pas se substituer à une évaluation froide du rapport entre risque et bénéfice de chaque option.", "points": [{"position": 1, "label": "Considérer qu''une poursuite créerait un risque disproportionné", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : risque pour pilotes et habitants dans ces rues étroites.", "groups": [{"position": 1, "keywords": ["risque disproportionné", "rues étroites", "pilotes et habitants"]}]}, {"position": 2, "label": "Mettre en balance ce risque avec la gravité du phénomène récurrent", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sans que la pression légitime n''aggrave le danger global.", "groups": [{"position": 1, "keywords": ["mise en balance", "phénomène récurrent", "pas d''aggravation du danger"]}]}, {"position": 3, "label": "Privilégier l''identification différée plutôt que la poursuite immédiate", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traiter le phénomène sans créer de danger supplémentaire.", "groups": [{"position": 1, "keywords": ["identification différée", "renoncer à la poursuite", "sans danger supplémentaire"]}]}, {"position": 4, "label": "Ne pas laisser le défi apparent influencer la décision tactique", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Évaluation froide du rapport risque-bénéfice.", "groups": [{"position": 1, "keywords": ["pas influencée par le défi", "évaluation froide", "risque-bénéfice"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment organisez-vous l''identification différée de ces pilotes, alternative à la poursuite immédiate ?", "hint": "Renoncer à la poursuite ne signifie pas renoncer à traiter le phénomène, mais implique de mobiliser d''autres moyens d''identification.", "perfect": "Je mobilise les moyens disponibles pour identifier ces deux-roues et leurs conducteurs par d''autres biais que la poursuite directe, notamment en relevant les éléments distinctifs visibles des véhicules et des pilotes.\n\nJe sollicite les vidéos prises par les habitants depuis leurs balcons, ces enregistrements pouvant constituer des éléments précieux pour l''identification ultérieure des participants à ce rodéo motorisé.\n\nJe communique avec les moyens disponibles pour un éventuel repérage complémentaire de ce groupe une fois qu''il aura quitté ce quartier résidentiel, dans des conditions de circulation moins dangereuses pour une éventuelle interception ultérieure.\n\nJe consigne avec précision l''ensemble des éléments observés durant cette intervention, ces informations constituant la base d''une enquête qui pourra se poursuivre au-delà de ce seul moment d''observation.", "points": [{"position": 1, "label": "Mobiliser les moyens pour identifier par d''autres biais que la poursuite", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : éléments distinctifs des véhicules et pilotes.", "groups": [{"position": 1, "keywords": ["identification par d''autres biais", "éléments distinctifs", "sans poursuite"]}]}, {"position": 2, "label": "Solliciter les vidéos prises par les habitants depuis leurs balcons", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éléments précieux pour l''identification ultérieure.", "groups": [{"position": 1, "keywords": ["vidéos des habitants", "éléments précieux", "identification ultérieure"]}]}, {"position": 3, "label": "Communiquer pour un repérage complémentaire dans des conditions moins dangereuses", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Une fois le groupe hors du quartier résidentiel.", "groups": [{"position": 1, "keywords": ["repérage complémentaire", "conditions moins dangereuses", "hors du quartier"]}]}, {"position": 4, "label": "Consigner précisément les éléments observés pour la suite de l''enquête", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Base d''une enquête au-delà de l''observation immédiate.", "groups": [{"position": 1, "keywords": ["consigner précisément", "base de l''enquête", "au-delà de l''observation"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment répondez-vous à la pression légitime des riverains qui attendent une réponse ferme à ce phénomène récurrent ?", "hint": "L''absence de poursuite immédiate ne signifie pas l''absence de réponse ; il convient de communiquer clairement sur la suite donnée.", "perfect": "Je communique clairement aux riverains présents les raisons de ma décision de ne pas engager de poursuite immédiate, en leur expliquant que cette prudence vise à éviter d''aggraver le danger plutôt qu''à ignorer leur plainte légitime.\n\nJe les informe des démarches qui seront engagées pour identifier et traiter ce phénomène par d''autres moyens, cette information pouvant atténuer leur frustration face à l''absence d''intervention immédiate et visible.\n\nJe recueille leurs propres observations sur la récurrence de ce phénomène, ces éléments pouvant enrichir utilement le dossier transmis aux services compétents pour un traitement de fond de cette problématique.\n\nJe reste attentive à ne pas leur faire de promesses sur des résultats que je ne peux garantir, tout en les assurant que leur signalement est pris au sérieux et fera l''objet d''un suivi effectif.", "points": [{"position": 1, "label": "Communiquer clairement les raisons de ne pas poursuivre immédiatement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : éviter d''aggraver le danger sans ignorer la plainte.", "groups": [{"position": 1, "keywords": ["raisons communiquées", "éviter d''aggraver", "plainte non ignorée"]}]}, {"position": 2, "label": "Informer des démarches engagées pour traiter le phénomène autrement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Atténuer la frustration face à l''absence d''intervention visible.", "groups": [{"position": 1, "keywords": ["démarches engagées", "atténuer la frustration", "autres moyens"]}]}, {"position": 3, "label": "Recueillir leurs observations sur la récurrence du phénomène", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Enrichir le dossier transmis aux services compétents.", "groups": [{"position": 1, "keywords": ["observations recueillies", "récurrence documentée", "dossier enrichi"]}]}, {"position": 4, "label": "Ne pas promettre des résultats non garantis tout en assurant un suivi", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Signalement pris au sérieux avec suivi effectif.", "groups": [{"position": 1, "keywords": ["pas de fausse promesse", "signalement sérieux", "suivi effectif"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-cycliste-blesse-portiere', '{"slug": "routier-cycliste-blesse-portiere", "title": "La portière s''est ouverte au moment où il arrivait", "theme_slug": "circulation", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 h 30. Vous intervenez sur une piste cyclable où un cycliste a été percuté par la portière d''un véhicule en stationnement qui s''est ouverte au moment précis où il arrivait à sa hauteur. Le cycliste est au sol, visiblement blessé, se plaignant de douleurs à l''épaule et au genou, tandis que le conducteur du véhicule, sorti précipitamment, affirme n''avoir vu personne arriver avant d''ouvrir sa portière.\n\nLa circulation sur cette piste cyclable continue autour de la scène, d''autres cyclistes devant contourner l''accident dans des conditions qui restent elles-mêmes à sécuriser. Le conducteur, visiblement inquiet des conséquences pour lui-même, commence à évoquer une responsabilité partagée du cycliste qui roulerait, selon lui, trop vite sur cette portion de piste.\n\nCette configuration, opposant un usager vulnérable blessé à un conducteur qui invoque déjà des éléments de défense, nécessite un traitement structuré qui priorise les secours avant d''aborder la question de la responsabilité de l''accident.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre priorité immédiate face à ce cycliste blessé au sol sur une piste toujours circulée ?", "hint": "Les secours et la sécurisation de la zone doivent précéder toute discussion sur les responsabilités respectives.", "perfect": "Ma priorité immédiate est l''évaluation et la prise en charge du cycliste blessé, ses douleurs à l''épaule et au genou nécessitant une attention rapide avant toute autre considération relative aux circonstances de l''accident.\n\nJe sécurise la zone de la piste cyclable pour éviter que d''autres cyclistes ne soient exposés à un risque supplémentaire en contournant la scène dans des conditions dangereuses.\n\nJe déclenche les secours médicaux adaptés à ses blessures, sans attendre d''avoir recueilli au préalable les explications du conducteur sur les circonstances de cette collision.\n\nJe reste attentive à ne pas déplacer le cycliste avant l''arrivée des secours, sauf nécessité absolue liée à un danger immédiat, cette précaution étant essentielle en cas de blessure potentiellement plus grave qu''elle n''apparaît au premier abord.", "points": [{"position": 1, "label": "Prioriser l''évaluation et la prise en charge du cycliste blessé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : secours avant toute autre considération.", "groups": [{"position": 1, "keywords": ["prise en charge prioritaire", "blessures évaluées", "avant autre considération"]}]}, {"position": 2, "label": "Sécuriser la zone de la piste cyclable pour les autres usagers", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter un risque supplémentaire pour les autres cyclistes.", "groups": [{"position": 1, "keywords": ["sécuriser la zone", "autres cyclistes", "risque supplémentaire"]}]}, {"position": 3, "label": "Déclencher les secours médicaux sans attendre les explications du conducteur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Secours prioritaires sur le recueil des circonstances.", "groups": [{"position": 1, "keywords": ["secours déclenchés", "sans attendre les explications", "priorité aux soins"]}]}, {"position": 4, "label": "Ne pas déplacer le cycliste sauf nécessité absolue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Précaution en cas de blessure plus grave qu''apparente.", "groups": [{"position": 1, "keywords": ["pas de déplacement", "sauf nécessité absolue", "blessure potentiellement grave"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous les constatations objectives face à ce conducteur qui évoque déjà une responsabilité partagée ?", "hint": "Le discours défensif précoce du conducteur ne doit pas orienter prématurément votre recueil des faits vers sa version.", "perfect": "Je recueille les constatations objectives de la scène, notamment la position du véhicule, l''angle d''ouverture de la portière et la position du cycliste au sol, ces éléments matériels étant indépendants des versions verbales de chacun.\n\nJe ne me laisse pas influencer par le discours défensif précoce du conducteur sur la vitesse supposée du cycliste, cette affirmation devant être vérifiée par des éléments objectifs plutôt qu''acceptée comme un fait établi.\n\nJe recueille également, une fois les secours du cycliste engagés, sa propre version des faits sur les circonstances de cette collision, sans que sa position de victime blessée ne prévale automatiquement sur la nécessité de recueillir les deux versions.\n\nJe recherche l''existence de témoins éventuels ayant assisté à la scène, ces témoignages extérieurs pouvant éclairer objectivement une situation où les deux parties ont un intérêt à présenter leur propre version favorablement.", "points": [{"position": 1, "label": "Recueillir les constatations objectives de la scène", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : éléments matériels indépendants des versions.", "groups": [{"position": 1, "keywords": ["constatations objectives", "position du véhicule", "éléments matériels"]}]}, {"position": 2, "label": "Ne pas se laisser influencer par le discours défensif précoce du conducteur", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Affirmation à vérifier plutôt qu''acceptée comme fait établi.", "groups": [{"position": 1, "keywords": ["pas influencée", "discours défensif", "à vérifier"]}]}, {"position": 3, "label": "Recueillir aussi la version du cycliste sans prévalence automatique", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Les deux versions doivent être recueillies.", "groups": [{"position": 1, "keywords": ["version du cycliste", "deux versions", "pas de prévalence automatique"]}]}, {"position": 4, "label": "Rechercher l''existence de témoins éventuels", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éclairer objectivement une situation à intérêts opposés.", "groups": [{"position": 1, "keywords": ["témoins recherchés", "éclairage objectif", "intérêts opposés"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous la question de la vitesse du cycliste invoquée par le conducteur, sans disposer d''éléments objectifs immédiats ?", "hint": "Une allégation non vérifiée ne doit ni être écartée d''emblée ni être retenue sans élément matériel à l''appui.", "perfect": "Je ne rejette pas d''emblée cette allégation sur la vitesse du cycliste, celle-ci pouvant effectivement avoir une pertinence pour la compréhension complète de cet accident sur une piste cyclable.\n\nJe ne la retiens pas non plus comme un fait établi en l''absence de tout élément objectif permettant de la vérifier, cette prudence méthodologique s''appliquant de la même manière à l''ensemble des affirmations non vérifiées de cette affaire.\n\nJe consigne cette allégation comme un élément déclaratif du conducteur, clairement distingué des constatations objectives que j''ai pu moi-même effectuer sur les lieux de l''accident.\n\nJe recherche si des éléments, comme la configuration des lieux ou d''éventuels témoignages, peuvent apporter un éclairage sur la vitesse réelle du cycliste au moment des faits, sans me satisfaire de la seule impression du conducteur.", "points": [{"position": 1, "label": "Ne pas rejeter d''emblée l''allégation sur la vitesse", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : pertinence possible pour la compréhension complète.", "groups": [{"position": 1, "keywords": ["pas de rejet d''emblée", "pertinence possible", "compréhension complète"]}]}, {"position": 2, "label": "Ne pas la retenir comme fait établi sans élément objectif", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Prudence méthodologique appliquée à toutes les affirmations.", "groups": [{"position": 1, "keywords": ["pas retenue sans preuve", "prudence méthodologique", "toutes affirmations"]}]}, {"position": 3, "label": "Consigner comme élément déclaratif distinct des constatations objectives", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Distinction claire dans le rapport.", "groups": [{"position": 1, "keywords": ["élément déclaratif", "distinct des constatations", "clairement distingué"]}]}, {"position": 4, "label": "Rechercher des éléments d''éclairage sur la vitesse réelle", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Configuration des lieux ou témoignages.", "groups": [{"position": 1, "keywords": ["éléments d''éclairage", "configuration des lieux", "pas seulement l''impression"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-deux-roues-sans-casque-fuite', '{"slug": "routier-deux-roues-sans-casque-fuite", "title": "Il accélère dès qu''il vous voit, sans casque, passager derrière", "theme_slug": "circulation", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 19 heures. Vous apercevez un deux-roues circulant sans casque sur un boulevard, avec un passager également non protégé installé derrière le conducteur. Dès qu''il vous aperçoit, le conducteur accélère nettement, engageant une fuite qui expose immédiatement le passager, totalement sans protection, à un risque physique considérablement accru par cette vitesse plus élevée.\n\nCette configuration particulière, où la fuite elle-même aggrave le danger déjà présent du fait de l''absence de casque des deux occupants, pose la question spécifique de l''arbitrage entre la volonté d''interpeller ce conducteur en infraction et le risque immédiat que cette poursuite ferait courir au passager, qui n''est peut-être pas à l''origine de cette décision de fuir.\n\nLe passager, dont vous ne savez rien du degré de consentement à cette fuite, se trouve exposé à un danger qu''il n''a peut-être pas lui-même choisi, cette situation nécessitant une évaluation rapide de la conduite à tenir face à ce risque spécifique et immédiat.", "questions": [{"position": 1, "max_points": 5, "label": "Comment évaluez-vous le risque spécifique que cette fuite fait courir au passager non protégé et non casqué ?", "hint": "Le passager subit un risque aggravé par la fuite sans nécessairement en être à l''origine, ce qui doit peser lourdement dans l''arbitrage tactique.", "perfect": "J''évalue ce risque comme particulièrement élevé, l''absence de casque des deux occupants combinée à l''accélération de fuite créant une exposition physique considérablement accrue par rapport à une simple infraction de circulation sans casque à vitesse modérée.\n\nJe reste attentive au fait que le passager n''est peut-être pas à l''origine de cette décision de fuir, cette incertitude sur son consentement réel devant peser dans l''appréciation du risque que je fais courir à une personne potentiellement non responsable de ce choix.\n\nJe considère que ce risque spécifique pour le passager doit primer sur ma volonté légitime d''interpeller ce conducteur en infraction, cette priorité de sécurité physique dépassant l''enjeu de la seule sanction de l''infraction initiale.\n\nJe garde à l''esprit que toute poursuite prolongée aggraverait mécaniquement ce risque déjà élevé, chaque seconde supplémentaire de vitesse augmentée exposant davantage ces deux occupants non protégés.", "points": [{"position": 1, "label": "Évaluer le risque comme particulièrement élevé du fait de la combinaison", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : absence de casque et accélération combinées.", "groups": [{"position": 1, "keywords": ["risque particulièrement élevé", "absence de casque combinée", "accélération de fuite"]}]}, {"position": 2, "label": "Considérer que le passager n''est peut-être pas à l''origine de la fuite", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Incertitude sur son consentement réel à peser.", "groups": [{"position": 1, "keywords": ["passager pas à l''origine", "consentement incertain", "responsabilité non partagée"]}]}, {"position": 3, "label": "Faire primer ce risque spécifique sur la volonté d''interpeller", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Sécurité physique dépassant l''enjeu de la sanction.", "groups": [{"position": 1, "keywords": ["risque prime sur l''interpellation", "sécurité physique", "au-delà de la sanction"]}]}, {"position": 4, "label": "Considérer que toute poursuite prolongée aggraverait le risque", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Chaque seconde supplémentaire augmentant l''exposition.", "groups": [{"position": 1, "keywords": ["poursuite aggraverait", "chaque seconde", "exposition accrue"]}]}]}, {"position": 2, "max_points": 5, "label": "Quelle décision tactique prenez-vous face à ce risque immédiat pour le passager ?", "hint": "L''arbitrage doit se traduire concrètement par un renoncement à l''escalade de la poursuite au profit d''une identification différée.", "perfect": "Je renonce à toute poursuite qui aggraverait la vitesse de ce deux-roues, cette décision étant directement guidée par le risque physique immédiat et considérable que cela ferait courir au passager non protégé.\n\nJe privilégie une identification différée du conducteur et de son véhicule par les moyens disponibles, cette approche permettant de traiter l''infraction sans exposer davantage ces deux occupants à un risque physique majeur.\n\nJe transmets sans délai les éléments d''identification dont je dispose, notamment la description du deux-roues et de ses occupants, pour permettre une interpellation ultérieure dans des conditions plus sécurisées.\n\nJe reste attentive à ne pas laisser ma frustration face à cette fuite influencer ma décision tactique, cette dernière devant rester guidée uniquement par l''évaluation objective du risque encouru par le passager.", "points": [{"position": 1, "label": "Renoncer à toute poursuite aggravant la vitesse du deux-roues", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : décision guidée par le risque pour le passager.", "groups": [{"position": 1, "keywords": ["renoncer à la poursuite", "risque pour le passager", "décision guidée"]}]}, {"position": 2, "label": "Privilégier une identification différée plutôt qu''une poursuite", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Traiter l''infraction sans exposer davantage.", "groups": [{"position": 1, "keywords": ["identification différée", "sans exposer davantage", "traiter l''infraction autrement"]}]}, {"position": 3, "label": "Transmettre sans délai les éléments d''identification disponibles", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Interpellation ultérieure dans des conditions sécurisées.", "groups": [{"position": 1, "keywords": ["éléments transmis", "interpellation ultérieure", "conditions sécurisées"]}]}, {"position": 4, "label": "Ne pas laisser la frustration influencer la décision tactique", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Décision guidée uniquement par l''évaluation objective du risque.", "groups": [{"position": 1, "keywords": ["pas de frustration", "évaluation objective", "risque encouru"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment poursuivez-vous cette affaire une fois le deux-roues hors de vue, sans avoir pu procéder à l''interpellation ?", "hint": "Le renoncement à la poursuite immédiate ne signifie pas l''abandon du traitement de cette infraction constatée.", "perfect": "Je consigne avec précision l''ensemble des éléments observés durant cette brève interaction, notamment la description du véhicule, des deux occupants et l''itinéraire emprunté au moment où ils ont échappé à ma vue.\n\nJe transmets ces éléments aux services compétents pour une éventuelle identification ultérieure, cette transmission permettant de poursuivre le traitement de cette infraction malgré l''absence d''interpellation immédiate.\n\nJe reste attentive à documenter précisément les raisons de mon renoncement à la poursuite, ce choix tactique devant être justifié clairement par le risque spécifique identifié pour le passager non protégé.\n\nJe considère cette affaire comme n''étant pas close du seul fait de cette fuite réussie, la poursuite de l''enquête par d''autres moyens restant une option à explorer plutôt qu''un simple abandon du dossier.", "points": [{"position": 1, "label": "Consigner précisément les éléments observés durant l''interaction", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : description utile pour identification ultérieure.", "groups": [{"position": 1, "keywords": ["consigner précisément", "description du véhicule", "itinéraire emprunté"]}]}, {"position": 2, "label": "Transmettre aux services compétents pour identification ultérieure", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Poursuivre le traitement malgré l''absence d''interpellation.", "groups": [{"position": 1, "keywords": ["transmission aux services", "identification ultérieure", "traitement poursuivi"]}]}, {"position": 3, "label": "Documenter précisément les raisons du renoncement à la poursuite", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Justifier le choix tactique par le risque identifié.", "groups": [{"position": 1, "keywords": ["raisons documentées", "choix tactique justifié", "risque identifié"]}]}, {"position": 4, "label": "Considérer que l''affaire n''est pas close malgré la fuite réussie", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Poursuite de l''enquête par d''autres moyens.", "groups": [{"position": 1, "keywords": ["pas close", "enquête poursuivie", "autres moyens"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-stationnement-genant-intervention', '{"slug": "routier-stationnement-genant-intervention", "title": "Le camion de pompiers ne passe pas, le propriétaire est introuvable", "theme_slug": "circulation", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 21 heures. Un véhicule mal stationné dans une rue étroite empêche le passage d''un camion de pompiers engagé sur une intervention urgente, un incendie signalé dans un immeuble proche nécessitant un accès rapide que ce blocage matériel compromet directement. Le propriétaire du véhicule reste introuvable malgré les appels lancés dans le voisinage immédiat, et chaque minute supplémentaire retarde l''arrivée des secours sur les lieux de l''incendie.\n\nCette situation, banale dans son origine d''un simple stationnement gênant, prend un caractère d''urgence exceptionnel du fait de l''intervention de pompiers bloquée par cet obstacle matériel, transformant un problème habituellement mineur en une urgence qui met potentiellement en jeu des vies humaines dans l''immeuble concerné par l''incendie.\n\nAucune option ne permet d''attendre le retour hypothétique du propriétaire, cette temporisation étant manifestement incompatible avec l''urgence de l''intervention des pompiers qui doit se dérouler sans délai supplémentaire.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre priorité absolue face à ce blocage qui empêche l''intervention des pompiers ?", "hint": "L''urgence vitale de l''intervention en cours doit primer sur toute autre considération relative au véhicule mal stationné.", "perfect": "Ma priorité absolue est de débloquer sans délai l''accès pour le camion de pompiers, cette urgence vitale liée à l''incendie en cours primant sur toute autre considération relative au véhicule mal stationné et à son propriétaire.\n\nJe ne perds pas de temps à chercher davantage le propriétaire au-delà des tentatives déjà effectuées, cette recherche prolongée étant manifestement incompatible avec l''urgence de l''intervention des pompiers qui ne peut attendre.\n\nJe considère que chaque minute supplémentaire de blocage aggrave potentiellement les conséquences de cet incendie pour les personnes présentes dans l''immeuble concerné, cette urgence vitale justifiant une action immédiate et décisive.\n\nJe reste concentrée sur cet objectif de déblocage rapide, sans me laisser distraire par des considérations secondaires qui pourraient retarder inutilement cette action urgente.", "points": [{"position": 1, "label": "Débloquer sans délai l''accès pour le camion de pompiers", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : urgence vitale primant sur toute autre considération.", "groups": [{"position": 1, "keywords": ["débloquer sans délai", "urgence vitale prime", "accès pompiers"]}]}, {"position": 2, "label": "Ne pas perdre de temps à chercher davantage le propriétaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Recherche prolongée incompatible avec l''urgence.", "groups": [{"position": 1, "keywords": ["pas de recherche prolongée", "incompatible avec l''urgence", "action immédiate"]}]}, {"position": 3, "label": "Considérer que chaque minute aggrave les conséquences de l''incendie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Urgence vitale justifiant une action décisive.", "groups": [{"position": 1, "keywords": ["chaque minute compte", "conséquences aggravées", "action décisive"]}]}, {"position": 4, "label": "Rester concentrée sur le déblocage rapide sans distraction", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éviter les considérations secondaires retardant l''action.", "groups": [{"position": 1, "keywords": ["concentrée sur l''objectif", "pas de distraction", "action non retardée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment procédez-vous concrètement pour débloquer cet accès dans les meilleurs délais ?", "hint": "L''action concrète de déblocage doit être menée avec les moyens disponibles les plus rapides, adaptés à cette urgence exceptionnelle.", "perfect": "J''engage sans délai les moyens disponibles pour déplacer ce véhicule, qu''il s''agisse d''un moyen d''enlèvement rapide ou de toute autre solution technique permettant de dégager l''accès le plus vite possible.\n\nJe coordonne cette action avec les services de secours présents sur place, cette coordination étant essentielle pour que le déblocage se fasse dans le sens et selon les modalités les plus utiles à la progression rapide du camion de pompiers.\n\nJe reste attentive à la sécurité de cette opération de déblocage elle-même, un geste précipité ne devant pas créer de nouveaux risques alors que l''objectif est justement de résoudre une situation d''urgence.\n\nJe documente les circonstances exceptionnelles de cette action, cette traçabilité étant utile pour justifier a posteriori une intervention qui aurait normalement nécessité l''accord ou la présence du propriétaire du véhicule.", "points": [{"position": 1, "label": "Engager sans délai les moyens disponibles pour déplacer le véhicule", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : dégager l''accès le plus vite possible.", "groups": [{"position": 1, "keywords": ["moyens engagés sans délai", "déplacer le véhicule", "dégager l''accès"]}]}, {"position": 2, "label": "Coordonner cette action avec les services de secours présents", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Modalités utiles à la progression du camion.", "groups": [{"position": 1, "keywords": ["coordination avec les secours", "modalités utiles", "progression du camion"]}]}, {"position": 3, "label": "Rester attentive à la sécurité de l''opération de déblocage", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas créer de nouveaux risques par précipitation.", "groups": [{"position": 1, "keywords": ["sécurité de l''opération", "pas de nouveaux risques", "précipitation évitée"]}]}, {"position": 4, "label": "Documenter les circonstances exceptionnelles de cette action", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traçabilité utile pour justifier a posteriori.", "groups": [{"position": 1, "keywords": ["documenter les circonstances", "traçabilité", "justification a posteriori"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous la situation du propriétaire du véhicule une fois l''urgence des pompiers résolue ?", "hint": "L''action d''urgence effectuée sans le consentement du propriétaire nécessite un traitement rigoureux de sa situation une fois le danger écarté.", "perfect": "Je m''assure que le propriétaire du véhicule puisse être informé dès que possible des circonstances qui ont conduit à cette action exceptionnelle sur son bien, cette transparence étant nécessaire malgré l''urgence qui a présidé à cette décision.\n\nJe consigne avec précision l''ensemble des circonstances de cette intervention, notamment l''urgence vitale qui l''a justifiée et les tentatives de recherche du propriétaire préalablement effectuées.\n\nJe reste factuelle dans la présentation de cette action au propriétaire, sans céder à la tentation de minimiser les conséquences pour son véhicule au nom de la légitimité de l''urgence invoquée.\n\nJe traite l''infraction de stationnement gênant elle-même de manière appropriée, cette qualification restant distincte de l''action d''urgence qui a dû être engagée du fait de ce stationnement problématique.", "points": [{"position": 1, "label": "S''assurer que le propriétaire soit informé des circonstances", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : transparence malgré l''urgence de la décision.", "groups": [{"position": 1, "keywords": ["propriétaire informé", "transparence nécessaire", "malgré l''urgence"]}]}, {"position": 2, "label": "Consigner précisément les circonstances de l''intervention", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Urgence vitale et tentatives de recherche préalables.", "groups": [{"position": 1, "keywords": ["consigner précisément", "urgence justifiée", "tentatives préalables"]}]}, {"position": 3, "label": "Rester factuelle sans minimiser les conséquences pour le propriétaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas minimiser au nom de la légitimité de l''urgence.", "groups": [{"position": 1, "keywords": ["factuelle", "pas de minimisation", "conséquences réelles"]}]}, {"position": 4, "label": "Traiter l''infraction de stationnement gênant de manière appropriée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Qualification distincte de l''action d''urgence.", "groups": [{"position": 1, "keywords": ["infraction traitée", "qualification distincte", "stationnement gênant"]}]}]}]}'::jsonb);